func TestFilesService_Add(t *testing.T) {
	t.Parallel()

	content := []byte("file-contents")
	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("X-Test"); got != "upload" {
			t.Fatalf("unexpected header X-Test: %q", got)
		}

		fileName, fields := parseMultipartRequest(t, r)
		if fileName != "upload.txt" {
			t.Fatalf("unexpected file name: %s", fileName)
		}
		if !bytes.Equal(fields["file"], content) {
			t.Fatalf("unexpected file content: %q", fields["file"])
		}
		wantFields := map[string]string{
			"deal_id":    "3",
			"person_id":  "7",
			"org_id":     "11",
			"product_id": "13",
			"lead_id":    "adf21080-0e10-11eb-879b-05d71fb426ec",
		}
		for name, value := range wantFields {
			if got := string(fields[name]); got != value {
				t.Fatalf("unexpected field %s: %q", name, got)
			}
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	file, err := client.Files.Add(
		context.Background(),
		"upload.txt",
		bytes.NewReader(content),
		WithFileDealID(DealID(3)),
		WithFilePersonID(PersonID(7)),
		WithFileOrganizationID(OrganizationID(11)),
		WithFileProductID(ProductID(13)),
		WithFileLeadID(LeadID("adf21080-0e10-11eb-879b-05d71fb426ec")),
		WithFilesRequestOptions(pipedrive.WithHeader("X-Test", "upload")),
	)
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if file.ID != 12 || file.Name != "upload.txt" {
		t.Fatalf("unexpected file: %#v", file)
	}
}
